mapper.select:
SELECT n.id, n.user_id AS userId, n.actor_user_id AS actorUserId, COALESCE(up.nickname, u.username) AS actorName, up.avatar_url AS actorAvatar, n.type, n.title, n.content, n.target_type AS targetType, n.target_id AS targetId, n.link_url AS linkUrl, n.is_read AS isRead, n.created_at AS createdAt FROM notifications n LEFT JOIN users u ON u.id = n.actor_user_id LEFT JOIN user_profiles up ON up.user_id = n.actor_user_id WHERE n.user_id = #{userId}
AND n.is_read = 0
ORDER BY n.created_at DESC, n.id DESC LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE notifications
SET is_read = 1
WHERE id = #{id}
  AND user_id = #{userId}
